SELECT gen_random_uuid(), c.save_game_id, c.id, 'PREPARADOR_FISICO', 'BOM', 'Leandro Duda', 45000.00, 13, 12
FROM clubs c
JOIN save_games g ON g.id = c.save_game_id
WHERE c.short_name = 'SPT'
  AND NOT EXISTS (SELECT 1 FROM staff s
                   WHERE s.club_id = c.id AND s.role = 'PREPARADOR_FISICO')
  AND NOT EXISTS (SELECT 1 FROM staff s
                   WHERE s.save_game_id = c.save_game_id AND s.name = 'Leandro Duda');
