INSERT INTO staff (id, save_game_id, club_id, role, quality, name, wage,
                   primary_attribute, secondary_attribute)
SELECT gen_random_uuid(), c.save_game_id, c.id, 'TECNICO', 'EXCELENTE', 'Guto Ferreira', 80000.00, 16, 15
FROM clubs c
JOIN save_games g ON g.id = c.save_game_id
WHERE c.short_name = 'VIL'
  AND NOT EXISTS (SELECT 1 FROM staff s
                   WHERE s.club_id = c.id AND s.role = 'TECNICO')
  AND NOT EXISTS (SELECT 1 FROM staff s
                   WHERE s.save_game_id = c.save_game_id AND s.name = 'Guto Ferreira')
  AND c.id IS DISTINCT FROM g.managed_club_id;
